<?php
declare(strict_types=1);
namespace Modules\Integrations;

final class Support
{
    public const PROVIDERS = ['onec'=>'1С','onec-yakovlev'=>'1С ИП Яковлев','diadoc'=>'Диадок','mosenergo'=>'Мосэнергосбыт','mosvodokanal'=>'Мосводоканал','pik'=>'ПИК-Комфорт','bank'=>'Банковская выписка · 1С','email'=>'Email','max'=>'MAX'];
    public static function uuid(): string { $b=random_bytes(16); $b[6]=chr((ord($b[6])&15)|64); $b[8]=chr((ord($b[8])&63)|128); $h=bin2hex($b); return substr($h,0,8).'-'.substr($h,8,4).'-'.substr($h,12,4).'-'.substr($h,16,4).'-'.substr($h,20); }
    public static function json(mixed $v): string {return json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_PRESERVE_ZERO_FRACTION|JSON_THROW_ON_ERROR);}
    public static function scriptJson(mixed $v): string {return json_encode($v,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);}
    public static function canonical(mixed $v): string {$sort=function(mixed $x)use(&$sort):mixed {if(!is_array($x))return $x;if(!array_is_list($x))ksort($x,SORT_STRING);foreach($x as &$item)$item=$sort($item);unset($item);return $x;};return self::json($sort($v));}
    public static function decode(string $raw): mixed {
        self::uniqueKeys($raw);
        // Preserve decimal JSON lexemes as strings before PHP could round them to binary floats.
        $out='';$length=strlen($raw);$quoted=false;$escape=false;
        for($i=0;$i<$length;$i++){$c=$raw[$i];if($quoted){$out.=$c;if($escape)$escape=false;elseif($c==='\\')$escape=true;elseif($c==='"')$quoted=false;continue;}if($c==='"'){$quoted=true;$out.=$c;continue;}if($c==='-'||ctype_digit($c)){$start=$i;while($i+1<$length&&str_contains('0123456789.eE+-',$raw[$i+1]))$i++;$n=substr($raw,$start,$i-$start+1);if(!preg_match('/^-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?$/D',$n))throw new \InvalidArgumentException('INVALID_JSON_NUMBER');if(str_contains(strtolower($n),'e')){$parts=preg_split('/[eE]/',$n);$power=(int)$parts[1];if(abs($power)>1000)throw new \InvalidArgumentException('EXPONENT_TOO_LARGE');$negative=str_starts_with($parts[0],'-');$mantissa=ltrim($parts[0],'-');$dot=strpos($mantissa,'.');$point=($dot===false?strlen($mantissa):$dot)+$power;$digits=str_replace('.','',$mantissa);$n=($negative?'-':'').($point<=0?'0.'.str_repeat('0',-$point).$digits:($point>=strlen($digits)?$digits.str_repeat('0',$point-strlen($digits)):substr($digits,0,$point).'.'.substr($digits,$point)));$out.='"'.$n.'"';}else $out.=str_contains($n,'.')?'"'.$n.'"':$n;}else $out.=$c;}
        return json_decode($out,true,64,JSON_THROW_ON_ERROR|JSON_BIGINT_AS_STRING);
    }
    private static function uniqueKeys(string $raw): void {
        $position=0;$length=strlen($raw);$ws=static function()use(&$position,$raw,$length){while($position<$length&&str_contains(" \r\n\t",$raw[$position]))$position++;};
        $string=static function()use(&$position,$raw,$length):string {$start=$position++;while($position<$length){if($raw[$position]==='\\'){$position+=2;continue;}if($raw[$position++]==='"')return json_decode(substr($raw,$start,$position-$start),true,8,JSON_THROW_ON_ERROR);}throw new \InvalidArgumentException('INVALID_JSON_STRING');};
        $value=function(int $depth=0)use(&$value,&$position,$raw,$length,$ws,$string):void {if($depth>64)throw new \InvalidArgumentException('JSON_DEPTH');$ws();$c=$raw[$position]??'';if($c==='{'){$position++;$ws();if(($raw[$position]??'')==='}'){$position++;return;}$seen=[];do{$ws();if(($raw[$position]??'')!=='"')throw new \InvalidArgumentException('JSON_KEY_REQUIRED');$key=$string();if(isset($seen[$key]))throw new \InvalidArgumentException('DUPLICATE_JSON_KEY');$seen[$key]=true;$ws();if(($raw[$position++]??'')!==':')throw new \InvalidArgumentException('INVALID_JSON_OBJECT');$value($depth+1);$ws();$delimiter=$raw[$position++]??'';if($delimiter==='}')return;if($delimiter!==',')throw new \InvalidArgumentException('INVALID_JSON_OBJECT');}while(true);}if($c==='['){$position++;$ws();if(($raw[$position]??'')===']'){$position++;return;}do{$value($depth+1);$ws();$delimiter=$raw[$position++]??'';if($delimiter===']')return;if($delimiter!==',')throw new \InvalidArgumentException('INVALID_JSON_ARRAY');}while(true);}if($c==='"'){$string();return;}$start=$position;while($position<$length&&!str_contains(" \r\n\t,]}",$raw[$position]))$position++;if($position===$start)throw new \InvalidArgumentException('INVALID_JSON_VALUE');};
        $value();$ws();if($position!==$length)throw new \InvalidArgumentException('INVALID_JSON_TRAILING_DATA');
